* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, sans-serif;
  background: #0f1115;
  color: #e8eaf0;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  max-width: 480px;
  margin: 0 auto;
  background: #14171c;
}

main {
  flex: 1;
  overflow-y: auto;
  padding: 1rem;
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 1rem;
}

h2 {
  font-size: 1.1rem;
  margin: 1.25rem 0 0.75rem;
}

h3 {
  font-size: 1rem;
  margin: 1rem 0 0.5rem;
}

.card {
  background: #1c2027;
  border-radius: 0.75rem;
  padding: 1rem;
  margin-bottom: 1rem;
}

button {
  background: #3b82f6;
  color: white;
  border: none;
  border-radius: 0.5rem;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  cursor: pointer;
  margin-right: 0.5rem;
  margin-bottom: 0.5rem;
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

button.primary {
  background: #8b5cf6;
  width: 100%;
}

.hint {
  color: #9ca3af;
  font-size: 0.85rem;
  margin: 0.75rem 0 0;
}

.empty {
  color: #6b7280;
  font-style: italic;
}

.list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.list-item {
  background: #1c2027;
  border-radius: 0.75rem;
  padding: 0.875rem;
  margin-bottom: 0.5rem;
  cursor: pointer;
}

.title {
  font-weight: 600;
}

.subtitle {
  color: #9ca3af;
  font-size: 0.85rem;
}

.toggle {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  cursor: pointer;
}

.tab-bar {
  display: flex;
  border-top: 1px solid #272b33;
  background: #1c2027;
}

.tab-bar button {
  flex: 1;
  background: transparent;
  color: #9ca3af;
  border-radius: 0;
  margin: 0;
  padding: 1rem;
}

.tab-bar button.active {
  color: #fff;
  border-top: 2px solid #8b5cf6;
}

.toast,
.error {
  position: fixed;
  bottom: 4.5rem;
  left: 50%;
  transform: translateX(-50%);
  padding: 0.75rem 1rem;
  border-radius: 0.5rem;
  max-width: 90%;
  text-align: center;
}

.toast {
  background: #10b981;
  color: white;
}

.error {
  background: #ef4444;
  color: white;
}

.modal {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.modal-content {
  background: #1c2027;
  border-radius: 1rem;
  padding: 1.25rem;
  max-height: 80vh;
  overflow-y: auto;
  width: 100%;
}

.tool-list {
  list-style: none;
  padding: 0;
}

.tool-list li {
  margin-bottom: 0.75rem;
}

