# Generated by curly apply. Deterministic brace-expansion helper.
# A value with no `{...}` groups always expands to exactly itself, so
# callers that never pass brace syntax see unchanged behavior.
from __future__ import annotations
from itertools import product
from typing import List


class BraceExpandError(ValueError):
    pass


def _split_top_level(text: str, sep: str = ",") -> List[str]:
    parts = []
    depth = 0
    start = 0
    for i, c in enumerate(text):
        if c == "{":
            depth += 1
        elif c == "}":
            if depth == 0:
                raise BraceExpandError("unmatched '}' while splitting brace alternatives")
            depth -= 1
        elif c == sep and depth == 0:
            parts.append(text[start:i])
            start = i + 1
    if depth != 0:
        raise BraceExpandError("unmatched '{' while splitting brace alternatives")
    parts.append(text[start:])
    return parts


def _parse_pieces(text: str):
    pieces = []
    depth = 0
    group_start = None
    literal_start = 0
    for i, c in enumerate(text):
        if c == "{":
            if depth == 0:
                if literal_start < i:
                    pieces.append(("literal", text[literal_start:i]))
                group_start = i
            depth += 1
        elif c == "}":
            if depth == 0:
                raise BraceExpandError(f"unmatched '}}' at position {i}")
            depth -= 1
            if depth == 0:
                content = text[group_start + 1 : i]
                alts = [_parse_pieces(a) for a in _split_top_level(content)]
                pieces.append(("choice", alts))
                literal_start = i + 1
                group_start = None
    if depth != 0:
        raise BraceExpandError(f"unmatched '{{' in {text!r}")
    if literal_start < len(text):
        pieces.append(("literal", text[literal_start:]))
    return pieces


def _expand_pieces(pieces) -> List[str]:
    results = [""]
    for kind, value in pieces:
        next_results = []
        if kind == "literal":
            for prefix in results:
                next_results.append(prefix + value)
        else:
            for prefix in results:
                for alt in value:
                    for expanded in _expand_pieces(alt):
                        next_results.append(prefix + expanded)
        results = next_results
    return results


def expand(token: str) -> List[str]:
    return _expand_pieces(_parse_pieces(token))


def expand_or_literal(token: str) -> List[str]:
    try:
        return expand(token)
    except BraceExpandError:
        return [token]


def cartesian(fields: List[List[str]]) -> List[List[str]]:
    return [list(combo) for combo in product(*fields)] if fields else [[]]

#!/usr/bin/env python3
"""Extract Amber's JSON payload from output that may include progress text."""

from __future__ import annotations

import json
import sys
from pathlib import Path


def extract_payload(raw: str) -> dict[str, object]:
    decoder = json.JSONDecoder()
    for offset, character in enumerate(raw):
        if character != "{":
            continue
        try:
            payload, _ = decoder.raw_decode(raw[offset:])
        except json.JSONDecodeError:
            continue
        if isinstance(payload, dict) and isinstance(payload.get("results"), list):
            return payload
    raise ValueError("Amber output did not contain a JSON object with a results array")


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: extract_amber_json.py INPUT OUTPUT", file=sys.stderr)
        return 2
    try:
        payload = extract_payload(Path(sys.argv[1]).read_text(encoding="utf-8"))
    except (OSError, UnicodeError, ValueError) as error:
        print(f"failed to normalize Amber report: {error}", file=sys.stderr)
        return 1
    Path(sys.argv[2]).write_text(
        json.dumps(payload, sort_keys=True, separators=(",", ":")) + "\n",
        encoding="utf-8",
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Regression tests for CI-safe Amber JSON extraction."""

import unittest

from extract_amber_json import extract_payload


class ExtractAmberJsonTests(unittest.TestCase):
    def test_accepts_plain_json(self) -> None:
        self.assertEqual(extract_payload('{"results":[]}'), {"results": []})

    def test_ignores_progress_and_trailing_output(self) -> None:
        payload = extract_payload(
            'INFO indexing\n  ✓ dependencies indexed\n{"results":[{"crate":"serde"}]}\ncomplete\n'
        )
        self.assertEqual(payload["results"], [{"crate": "serde"}])

    def test_rejects_unrelated_or_malformed_objects(self) -> None:
        with self.assertRaises(ValueError):
            extract_payload('INFO {not-json}\n{"status":"done"}')


if __name__ == "__main__":
    unittest.main()

