#[derive(Debug, Deserialize)]
struct CloudInferenceResponse {
    content: String,
    #[serde(default)]
    usage: Usage,
    provider: String,
    model: String,
}

#[derive(Debug, Serialize)]
struct AnthropicRequest<'a> {
    model: &'a str,
    max_tokens: usize,
    temperature: f32,
    #[serde(skip_serializing_if = "Option::is_none")]
    system: Option<&'a str>,
    messages: Vec<AnthropicMessage<'a>>,
}

#[derive(Debug, Serialize)]
struct AnthropicMessage<'a> {
    role: &'a str,
    content: &'a str,
}

#[derive(Debug, Deserialize)]
struct AnthropicResponse {
    content: Vec<AnthropicContentBlock>,
    #[serde(default)]
    usage: AnthropicUsage,
}

#[derive(Debug, Deserialize)]
struct AnthropicContentBlock {
    #[serde(rename = "type", default)]
    block_type: String,
    #[serde(default)]
    text: String,
}

#[derive(Debug, Default, Deserialize)]
struct AnthropicUsage {
    #[serde(default)]
    input_tokens: usize,
    #[serde(default)]
    output_tokens: usize,
}

/// Which request/response shape a route speaks. Most third-party providers
/// (and all of Dreamsequence's own BYOK defaults before this) are OpenAI-
/// compatible; Anthropic's Messages API is shaped differently enough
/// (`x-api-key` auth, a top-level `system` field, typed content blocks) to
/// need its own dispatch — see `request_anthropic` in inference_transport.rs.
/// Public so `config::ProviderSettings` (a manually-configured provider,
/// persisted to disk by the `dreamseq config` TUI) can name it directly.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Protocol {
    #[default]
    OpenAiCompatible,
    Anthropic,
}

impl Protocol {
    pub fn label(&self) -> &'static str {
        match self {
            Self::OpenAiCompatible => "openai_compatible",
            Self::Anthropic => "anthropic",
        }
    }

    pub fn toggled(&self) -> Self {
        match self {
            Self::OpenAiCompatible => Self::Anthropic,
            Self::Anthropic => Self::OpenAiCompatible,
        }
    }
}

#[derive(Clone)]
pub(super) struct InferenceRoute {
    name: String,
    base_url: String,
    model: String,
    api_key: String,
    /// A cheaper/faster model for batches BatchComplexity classifies as
    /// light, mirroring dreamsequence-api's server-side tier split. Also
    /// used to rank routes for light batches — see `ranked_byok_routes`.
    light_model: Option<String>,
    protocol: Protocol,
}

struct InferenceOutput {
    content: String,
    tokens_used: usize,
    provider: String,
    model: String,
}

/// A completed batch's analysis plus which route actually served it. The
/// server already relays this on every response (see `InferenceOutput`
/// above); this struct carries it out of `analyze_prompt`/`attempt_route`
/// so the caller can report it, instead of the provider/model being logged
/// once via `tracing::info!` (invisible without `--verbose`) and discarded.
struct BatchOutcome {
    analysis: Analysis,
    provider: String,
    model: String,
}

