                ("GROK_API_KEY", None),
                ("XAI_MODEL", Some("grok-custom")),
            ],
            || {
                let mut routes = Vec::new();
                add_named_provider_routes(&mut routes);
                let route = routes
                    .iter()
                    .find(|route| route.name == "grok")
                    .expect("grok route should be detected");
                assert_eq!(route.model, "grok-custom");
            },
        );
    }

    #[test]
